const path = useComputedValue(() => {
  const d = Math.min(edge.current, MAX);
  const p = Skia.Path.Make();
  // build a simple liquid curve with a few control points
  p.moveTo(0, 0);
  p.cubicTo(W*0.25, d, W*0.75, d, W, 0);
