const effect = useMemo(() => Skia.RuntimeEffect.Make(glsl)!, []);
const t = useValue(0);
const sv = useSharedValue(0);
useFrameCallback(({ timeSinceFirstFrame }) => { sv.value = timeSinceFirstFrame / 1000; });
useSharedValueEffect(() => { t.current = sv.value; }, sv);

const uniforms = useComputedValue(() => ({
  u_time: t.current,
  u_resolution: [width, height],
  u_intensity: 0.8,
}), [t, width, height]);

